double ternarySearchContinuous(function<double(double)> f, double lo, double hi) {
    for (int iter = 0; iter < 100; iter++) { // fixed iteration count is simplest
        double m1 = lo + (hi - lo) / 3.0;
        double m2 = hi - (hi - lo) / 3.0;
        if (f(m1) < f(m2)) lo = m1;
        else hi = m2;
    }
    return (lo + hi) / 2.0;
}

int ternarySearchDiscrete(vector<int>& f, int lo, int hi) {
    while (hi - lo > 2) {
        int m1 = lo + (hi - lo) / 3;
        int m2 = hi - (hi - lo) / 3;
        if (f[m1] < f[m2]) lo = m1 + 1;
        else hi = m2 - 1; // guaranteeing the range strictly shrinks each iteration
    }
    int best = lo;
    for (int i = lo + 1; i <= hi; i++) if (f[i] > f[best]) best = i;
    return best;
}
